fn pending_not_sent(f:&mut F,l:&mut package_dispatch::PackageDispatchLog,w:&mut Wire){let _lost=staged(f,l,w);Wire::native_attempt(f);w.at=now()+3000;w.prepare(&f.bank,&f.admission,f.permit.clone(),f.facts.clone()).unwrap();let token=l.attempt(f.admission.package_id(),&stamp(w.at)).unwrap();let e=match w.send(f.admission.basket().clone(),f.permit.clone()){Err(e)=>e,Ok(_)=>panic!("expected local not-sent")};let proof=w.take_not_sent().unwrap();moloch_replay::session::atomic_json(&w.dir.join(format!("not-sent-{}.json",sha(&f.spec))),proof.evidence()).unwrap();l.not_sent(token,&e,&proof.attestation().unwrap(),&stamp(w.at)).unwrap();}
