fn reopen_bank(f:&mut F){let m:Value=serde_json::from_slice(&std::fs::read(f.path.join("manifest.json")).unwrap()).unwrap();let scratch=f.path.join("restart-placeholder");let blank=Session::open_live(&scratch,&m["policy"],&m["seed"]["evidence"]).unwrap();let old=std::mem::replace(&mut f.bank,blank);drop(old);let restored=Session::open_live(&f.path,&m["policy"],&m["seed"]["evidence"]).unwrap();f.bank=restored;let _=std::fs::remove_dir_all(scratch);}
#[test]fn one_actual_component_ack_before_restart_recovers_remaining_mapping_idempotently(){let mut f=F::make(false);let mut l=log(&f);let mut w=Wire::new(&f,Mode::Ack);let _lost=staged(&mut f,&mut l,&w);Wire::native_attempt(&mut f);w.at=now()+3000;w.prepare(&f.bank,&f.admission,f.permit.clone(),f.facts.clone()).unwrap();let _token=l.attempt(f.admission.package_id(),&stamp(w.at)).unwrap();let receipt=match w.send(f.admission.basket().clone(),f.permit.clone()).unwrap(){Outcome::FullFillReported{receipt,..}=>receipt,_=>panic!()};l.acknowledged(f.admission.package_id(),&receipt,&stamp(w.at)).unwrap();let p=f.bank.engine().package_records()[0].clone();let ack=package_feedback::acknowledgment(&f.bank,&p,f.admission.basket(),&f.scope,&f.permit,&receipt,&stamp(w.at)).unwrap();f.bank.accept("partial-ack",1,&ack["acknowledgments"][0]).unwrap();assert_eq!(f.bank.engine().live_order_bindings().len(),1);assert!(f.bank.engine().fills().is_empty());drop(l);reopen_bank(&mut f);let mut l=log(&f);package_worker::recover(&mut f.bank,&mut l,&mut w).unwrap();assert_eq!(f.bank.engine().live_order_bindings().len(),2);assert_eq!(f.bank.engine().fills().len(),3);assert_eq!(phase(&f),"complete");assert_eq!(w.calls,1);assert_eq!(w.reads,4);}

#[test]fn persisted_response_receive_clock_precedes_sdk_completion_without_losing_ack(){
 let mut f=F::make(false);let mut l=log(&f);let mut w=Wire::new(&f,Mode::Ack);
 assert_eq!(send(&mut f,&mut l,&mut w).unwrap(),SendResult::Acknowledged);
 let row=l.verified_record(f.admission.package_id()).unwrap();let r:Receipt=serde_json::from_value(row["outcome"]["receipt"].clone()).unwrap();
 let meta:Value=serde_json::from_slice(&std::fs::read(w.dir.join("original-response.meta")).unwrap()).unwrap();
 assert_eq!(r.request_started_at,meta["evidence"]["requestStartedAt"].as_str().unwrap());
 assert!(daily_windows::clock(meta["evidence"]["receivedAt"].as_str().unwrap()).unwrap()<daily_windows::clock(&r.received_at).unwrap());
 assert_eq!(r.received_at,stamp(w.at));assert_eq!(f.bank.engine().live_order_bindings().len(),2);assert!(f.bank.engine().fills().is_empty());
 // Both original files remain intact after native mapping; no clock was rewritten.
 let saved:Value=serde_json::from_slice(&std::fs::read(w.dir.join("original-response.meta")).unwrap()).unwrap();assert_eq!(saved,meta);
 let request:Value=serde_json::from_slice(&std::fs::read(w.dir.join("original-request.json")).unwrap()).unwrap();assert_eq!(request["request"],serde_json::to_value(&f.spec).unwrap());
}
