#[test]fn unknown_package_with_independently_bound_component_reads_only_that_full_tape_across_restart(){
 let mut f=F::make(false);let mut l=log(&f);let mut w=Wire::new(&f,Mode::Unknown);
 assert_eq!(send(&mut f,&mut l,&mut w).unwrap(),SendResult::Unknown);
 assert_eq!(w.queue.summary().unwrap().global_unknown_count,1);
 let p=f.bank.engine().package_records()[0].clone();let leg=&p["legs"][0];
 // Simulate an independent exact official identity reconciliation already
 // durably admitted by the sole owner. It binds only this one known component;
 // no complete basket ACK, other actual ID or acceptance resolution is invented.
 let official=Receipt{endpoint:"/orders/901".into(),status:200,request_started_at:stamp(w.at),received_at:stamp(w.at),data:json!({"id":"901","exchangeId":leg["exchangeId"],"tournamentId":T,"side":"no","action":"buy","quantity":leg["quantity"],"priceLimit":0.45,"open":true,"quantityFilled":0})};
 moloch_replay::session::atomic_json(&w.dir.join("independent-known-component.json"),&serde_json::to_value(&official).unwrap()).unwrap();
 let ack=json!({"type":"actual_order_ack","source":"official_sig_api_v1","receiptHash":feedback::digest(&official).unwrap(),"orderId":leg["qid"],"actualOrderId":"901","exchangeId":leg["exchangeId"],"marketId":leg["marketId"],"side":leg["side"],"action":"buy","quantity":leg["quantity"],"price":leg["limitPrice"],"receivedAt":official.received_at,"processedAt":stamp(w.at)});
 f.bank.accept("independent-known-component",1,&ack).unwrap();
 w.partial=true;let r=package_worker::recover(&mut f.bank,&mut l,&mut w).unwrap();assert!(r.blocks_new_submissions);assert_eq!(r.fill_events,1);assert_eq!(r.completed_packages,0);assert_eq!(w.reads,2);assert_eq!(f.bank.engine().fills().len(),1);assert_eq!(funding(&f)["reservedCash"],"7.300000");
 drop(l);reopen_bank(&mut f);let mut l=log(&f);w.partial=false;
 let r=package_worker::recover(&mut f.bank,&mut l,&mut w).unwrap();assert!(r.blocks_new_submissions);assert_eq!(r.fill_events,1);assert_eq!(r.completed_packages,0);assert_eq!(w.reads,4);assert_eq!(f.bank.engine().fills().len(),2);
 assert_eq!(phase(&f),"unknown");assert_eq!(l.verified_record(f.admission.package_id()).unwrap()["phase"],"unknown");assert_eq!(w.queue.summary().unwrap().global_unknown_count,1);assert_eq!(f.bank.engine().live_order_bindings().len(),1);assert_eq!(funding(&f)["reservedCash"],"5.050000");assert_eq!(funding(&f)["ownedCost"],"4.500000");assert_eq!(w.calls,1);
 let before=funding(&f);let r=package_worker::recover(&mut f.bank,&mut l,&mut w).unwrap();assert!(r.blocks_new_submissions);assert_eq!(r.fill_events,0);assert_eq!(w.reads,4);assert_eq!(funding(&f),before);assert_eq!(w.calls,1);
}

// Genuine SDK guard failure, not a caller-constructed empty-queue attestation.
// ReadOnlyAuthority denies before admission; DisabledCredentials prevents auth
// use even if that guard regresses. This fixture performs no account HTTP.
use std::sync::{Arc,atomic::{AtomicU64,Ordering}};
struct FirstClock(Arc<AtomicU64>);impl baal_transport_service::Clock for FirstClock{fn now_ms(&self)->u64{self.0.load(Ordering::SeqCst)}fn sleep_ms(&mut self,_:u64)->baal_transport_service::Result<()>{panic!("unexpected first-call admission wait")}}
struct FirstWire{sdk:baal_transport_service::Transport,at:Arc<AtomicU64>,dir:PathBuf,activation:authority::Activation,prepared:Option<Prepared>,calls:usize}
impl FirstWire{fn new(f:&F)->Self{let at=Arc::new(AtomicU64::new(now()));let dir=f.path.join("first-call-receipts");std::fs::create_dir_all(&dir).unwrap();let sdk=baal_transport_service::Transport::new(baal_transport_service::Config{queue_dir:f.path.join("first-call-actual-sdk"),account_scope:"fixture-account".into(),scope:f.scope.clone(),maximum_pages:4,writes_enabled:true},Box::new(baal_transport_service::DisabledCredentials),Box::new(FirstClock(at.clone())),Box::new(baal_transport_service::ReadOnlyAuthority)).unwrap();Self{sdk,at,dir,activation:f.a.clone(),prepared:None,calls:0}}fn time(&self,at:u64){self.at.store(at,Ordering::SeqCst);}}
impl Backend for FirstWire{
 fn now_ms(&self)->u64{self.at.load(Ordering::SeqCst)}fn scope(&self)->&Scope{self.sdk.scope()}fn account_scope(&self)->&str{self.sdk.account_scope()}fn evidence_directory(&self)->&Path{&self.dir}
 fn quiet(&self)->feedback::Result<()>{self.sdk.package_queue_quiet()?;Ok(())}
 fn lookup(&self,id:&str)->feedback::Result<BindingLookup>{Ok(self.sdk.admission_lookup_intent(id)?)}
 fn prepare(&mut self,bank:&Session,a:&package_admission::Admission,p:Permit,f:PackageSnapshotSet)->feedback::Result<()>{let ready=Prepared::new(bank,&self.activation,self.scope(),a,p.clone(),f,self.now_ms(),self.activation.entry_until_ms)?;ready.authorize(&multi_leg::request_spec(a.basket(),self.scope(),&p)?,&p,self.now_ms(),&BTreeSet::new(),self.activation.entry_until_ms)?;self.prepared=Some(ready);Ok(())}
 fn clear_ready(&mut self){self.prepared=None;}
 fn send(&mut self,b:Basket,p:Permit)->baal_transport_service::Result<Outcome>{self.calls+=1;self.sdk.place_all_or_none(b,p)}
 fn take_not_sent(&mut self)->feedback::Result<package_not_sent_evidence::VerifiedNotSent>{Ok(package_not_sent_evidence::VerifiedNotSent::from_sdk(self.sdk.take_local_not_sent_proof()?))}
 fn retained_not_sent(&mut self,b:&ImmutableBinding,r:&str,min:u64)->feedback::Result<package_not_sent_evidence::VerifiedNotSent>{Ok(package_not_sent_evidence::VerifiedNotSent::from_sdk(self.sdk.verify_retained_local_not_sent(b,r,min)?))}
 fn take_first_call_not_sent(&mut self)->feedback::Result<baal_transport_service::multi_leg_first_call::Proof>{Ok(self.sdk.take_first_call_no_http_proof()?)}
 fn retained_first_call_not_sent(&mut self,b:&ImmutableBinding,r:&str)->feedback::Result<baal_transport_service::multi_leg_first_call::Proof>{Ok(self.sdk.verify_retained_first_call_no_http(b,r)?)}
 fn bind_owned(&mut self,_:&str){panic!("no ACK allowed in first-call fixture")}
 fn read(&mut self,_:Endpoint)->feedback::Result<Receipt>{panic!("no account read allowed in first-call fixture")}
}
fn pending_first_call(f:&mut F,l:&mut package_dispatch::PackageDispatchLog,w:&mut FirstWire){
 let _lost=package_worker::stage(&mut f.bank,l,w,&f.admission,f.permit.clone()).unwrap();Wire::native_attempt(f);w.time(now()+3000);w.prepare(&f.bank,&f.admission,f.permit.clone(),f.facts.clone()).unwrap();let token=l.attempt(f.admission.package_id(),&stamp(w.now_ms())).unwrap();let error=w.send(f.admission.basket().clone(),f.permit.clone()).err().unwrap();let proof=w.take_first_call_not_sent().unwrap();moloch_replay::session::atomic_json(&w.dir.join(format!("first-call-not-sent-{}.json",sha(&f.spec))),proof.evidence()).unwrap();l.first_call_not_sent(token,&error,&proof,&stamp(w.now_ms())).unwrap();
}
#[test]fn genuine_sdk_frontdoor_denial_releases_only_reserved_funding_without_fills_or_profit(){let mut f=F::make(false);let mut l=log(&f);let mut w=FirstWire::new(&f);let s=package_worker::stage(&mut f.bank,&mut l,&w,&f.admission,f.permit.clone()).unwrap();w.time(now()+3000);let before=f.bank.engine().report().unwrap();assert_eq!(package_worker::submit_once(&mut f.bank,&mut l,&mut w,s,f.facts.clone()).unwrap(),SendResult::LocalNotSent);assert_eq!(phase(&f),"no_execution");assert_eq!(funding(&f)["reservedCash"],"0.000000");let after=f.bank.engine().report().unwrap();assert_eq!(after["cash"],before["cash"]);assert_eq!(after["realized"],before["realized"]);assert!(f.bank.engine().fills().is_empty()&&f.bank.engine().live_order_bindings().is_empty());assert_eq!(w.calls,1);assert_eq!(w.sdk.admission_summary().unwrap().sequence,0);assert_eq!(l.verified_record(f.admission.package_id()).unwrap()["phase"],"first_call_not_sent");assert!(!package_worker::recover(&mut f.bank,&mut l,&mut w).unwrap().blocks_new_submissions);}
#[test]fn restart_between_durable_first_call_outcome_and_native_release_reverifies_sdk_source(){let mut f=F::make(false);let mut l=log(&f);let mut w=FirstWire::new(&f);pending_first_call(&mut f,&mut l,&mut w);assert_eq!(phase(&f),"attempted");assert_eq!(funding(&f)["reservedCash"],"9.550000");drop(l);drop(w);reopen_bank(&mut f);let mut l=log(&f);let mut w=FirstWire::new(&f);w.time(now()+4000);let r=package_worker::recover(&mut f.bank,&mut l,&mut w).unwrap();assert!(!r.blocks_new_submissions);assert_eq!(phase(&f),"no_execution");assert_eq!(funding(&f)["reservedCash"],"0.000000");assert_eq!(w.calls,0);assert!(f.bank.engine().fills().is_empty());}
#[test]fn changed_or_missing_saved_first_call_proof_and_sdk_source_keep_funding_blocked(){for mode in 0..3{let mut f=F::make(false);let mut l=log(&f);let mut w=FirstWire::new(&f);pending_first_call(&mut f,&mut l,&mut w);let saved=w.dir.join(format!("first-call-not-sent-{}.json",sha(&f.spec)));match mode{0=>std::fs::remove_file(saved).unwrap(),1=>std::fs::write(saved,b"{}").unwrap(),_=>{let file=std::fs::read_dir(f.path.join("first-call-actual-sdk")).unwrap().map(|e|e.unwrap().path()).find(|p|p.file_name().unwrap().to_string_lossy().starts_with("first-call-terminal-")).unwrap();std::fs::write(file,b"{").unwrap();}}assert!(package_worker::recover(&mut f.bank,&mut l,&mut w).is_err());assert_eq!(phase(&f),"attempted");assert_eq!(funding(&f)["reservedCash"],"9.550000");assert!(f.bank.engine().fills().is_empty());assert_eq!(w.calls,1);}}
#[test]fn sdk_terminal_without_durable_first_call_dispatch_outcome_never_releases_on_restart(){let mut f=F::make(false);let mut l=log(&f);let mut w=FirstWire::new(&f);let _lost=package_worker::stage(&mut f.bank,&mut l,&w,&f.admission,f.permit.clone()).unwrap();Wire::native_attempt(&mut f);w.time(now()+3000);let _token=l.attempt(f.admission.package_id(),&stamp(w.now_ms())).unwrap();let _error=w.send(f.admission.basket().clone(),f.permit.clone()).err().unwrap();let _proof=w.take_first_call_not_sent().unwrap();drop(l);drop(w);reopen_bank(&mut f);let mut l=log(&f);let mut w=FirstWire::new(&f);w.time(now()+4000);assert!(package_worker::recover(&mut f.bank,&mut l,&mut w).unwrap().blocks_new_submissions);assert_eq!(phase(&f),"attempted");assert_eq!(funding(&f)["reservedCash"],"9.550000");assert_eq!(w.calls,0);}
